contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run tests with a withdrawal amount 'amt'
    function run(uint amt) public payable {
        // record before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // perform the state-changing call: attempt withdraw(amt)
        bool reverted;
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // If call did not revert, depositsCount must be unchanged and balance must decrease by min(amt, beforeBal)
        // If it reverted, no guarantee. This is our single general assertion.
        assert(reverted || (afterCount == beforeCount && afterBal + (beforeBal >= amt ? amt : beforeBal) == beforeBal));
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

